BankAccount.prepare(state);
const bankBaseSettings=settingsPage,bankBaseMy=myPage;
myPage=function(){const html=bankBaseMy();if(!current())return html;const box=document.createElement('div');box.innerHTML=html;box.querySelector('.panel')?.insertAdjacentHTML('beforeend',bankAccountGuide(state.settings,true));return box.innerHTML;};
settingsPage=function(){const box=document.createElement('div');box.innerHTML=bankBaseSettings();const b=state.settings.bankAccount||{};let html='<section class="panel"><h2>会費の振込先口座</h2><p>参加申込の期限案内に表示します。口座情報を変更できるのは管理者だけです。</p>';
if(owner())html+='<form id="bankAccountForm"><div class="grid-2">'+field('bankName','銀行名',b.bankName||'','text',false)+field('branchName','支店名',b.branchName||'','text',false)+select('accountType','口座種別',[['普通','普通'],['当座','当座']],b.accountType||'普通')+field('accountNumber','口座番号（7桁・先頭の0も入力）',b.accountNumber||'','text',false)+field('accountHolder','口座名義（カタカナ）',b.accountHolder||'','text',false)+'</div><p class="mini-note">公開サンプルでは架空口座だけを入力してください。このブラウザー内に保存します。すべて空欄で保存すると案内を取り下げます。</p>'+field('reason','変更理由')+'<p class="error-text" role="alert"></p><button class="btn">振込先口座を保存</button></form>';else html+=bankAccountGuide(state.settings)+'<p class="mini-note">幹事は閲覧のみです。変更は管理者に依頼してください。</p>';
box.querySelector('.admin-tabs').insertAdjacentHTML('afterend',html+'</section>');return box.innerHTML;};
document.addEventListener('submit',ev=>{const f=ev.target;if(f.id!=='bankAccountForm')return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));try{change(s=>BankAccount.save(s,d,current()?.id));route();toast('振込先口座と変更履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
route();
